t = int(input())
for i in range(t):
	n = int(input())
	a = list(map(int, input().split()))
	d = {}
	for j in a:
		d[j] = d.get(j, 0) + 1
	a.sort()
	s = 0
	c = 0
	for k in range(len(a)):
		if k == 0:
			s = 1
		elif a[k] != a[k - 1]:
			s = 1
		else:
			s += 1
		if d.get(s, 0) >= a[k]:
			c += 1
	print(c)
